import {decodeState,encodeState} from './physics.mjs';
export const galleryKey='fotolabor.photos.v1';
export function readGallery(storage){try{const list=JSON.parse(storage.getItem(galleryKey)||'[]');if(!Array.isArray(list))return [];return list.filter(p=>p&&typeof p.id==='string'&&/^[a-z0-9-]+$/.test(p.id)&&typeof p.image==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(p.image)&&p.image.length<800000&&Number.isFinite(p.time)&&Number.isFinite(p.created)).slice(-20).map(p=>({...p,state:decodeState('#s='+encodeState(p.state||{}))}));}catch{return [];}}
export function writeGallery(storage,photos){if(photos.length>20)throw new Error('Die Galerie enthält 20 Fotos. Exportieren oder löschen Sie eine Aufnahme, bevor Sie weitere speichern.');storage.setItem(galleryKey,JSON.stringify(photos));}

export function exportGallery(photos){return JSON.stringify({format:'camera-gallery',version:1,photos},null,2);}
export function importGallery(text,existing=[]){if(text.length>18000000)throw new Error('Die Galerie-Datei ist zu groß.');const raw=JSON.parse(text);if(raw.format!=='camera-gallery'||raw.version!==1||!Array.isArray(raw.photos)||raw.photos.length>20)throw new Error('Keine gültige Galerie-Datei.');const valid=readGallery({getItem:()=>JSON.stringify(raw.photos)});if(valid.length!==raw.photos.length)throw new Error('Die Galerie-Datei enthält ungültige Aufnahmen.');const map=new Map(existing.map(p=>[p.id,p]));for(const p of valid)if(!map.has(p.id))map.set(p.id,p);if(map.size>20)throw new Error('Die Galerie enthält dann mehr als 20 Fotos.');return [...map.values()];}
